{
  "source_context": [
    {
      "section": "V1",
      "lyrics": [
        "描いた地図は引き裂いた",
        "世界はあの日のまま",
        "僕はまた",
        "誰かのせいにした",
        "嫌になっちゃうな"
      ]
    },
    {
      "section": "B1",
      "lyrics": [
        "このまま何かを待ち続けるフリするの",
        "ここから僕はやりなおせますか"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "どこまでも行ける気がした",
        "あの時の僕はどこだ",
        "きっと大人になったとか",
        "そういうことじゃなくてさ",
        "あと少しだけの勇気で",
        "変えられた明日はあった",
        "それさえ気づけなかったんだ"
      ]
    },
    {
      "section": "O1",
      "lyrics": [
        "そんな日はもうたくさんだ",
        "いつまでもなんてないんだ",
        "終わりゆくその前に",
        "一歩踏み出してみた",
        "受け入れながら",
        "祈りながら"
      ]
    }
  ],
  "section": "B1",
  "phrases": [
    {
      "id": "B1-01",
      "ja": "このまま何かを待ち続けるフリするの",
      "budget": {
        "min": 18,
        "max": 18
      },
      "pattern": [
        4,
        3,
        6,
        5
      ]
    },
    {
      "id": "B1-02",
      "ja": "ここから僕はやりなおせますか",
      "budget": {
        "min": 14,
        "max": 14
      },
      "pattern": [
        6,
        8
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "就这样装作一直在等待着什么"
        },
        {
          "id": "B1-02",
          "zh": "从这儿我还能重新开始吗"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "就这样装作 还在等待什么 不肯醒来"
        },
        {
          "id": "B1-02",
          "zh": "从这里我还能 重新再来一次吗"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "就这样吧 装作等 一班不来的车 等到路灯亮"
        },
        {
          "id": "B1-02",
          "zh": "从这一步开始 我还能重新来过吗"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "楼梯转角 停住脚 假装还在等谁 等到灯熄灭"
        },
        {
          "id": "B1-02",
          "zh": "从这里再往前 我还能重新来过吗"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "就这样装作一直在等待着什么"
        },
        {
          "id": "B1-02",
          "zh": "从这里我能够重新开始吗"
        }
      ]
    },
    {
      "label": "F",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "就这样装作在等什么 一直等下去"
        },
        {
          "id": "B1-02",
          "zh": "从这里我还能重新来过吗"
        }
      ]
    }
  ]
}

